% Shovqinlar va ularning statistik tahlili
Fs = 1000;
t = 0:1/Fs:1;
f0 = 15;
signal_clean = sin(2*pi*f0*t);
noise = 0.4 * randn(size(t));
noisy_signal = signal_clean + noise;

P_sig = mean(signal_clean.^2);
P_noise = mean(noise.^2);
snr_calc = 10 * log10(P_sig / P_noise);
disp(['Signal-Shovqin nisbati SNR (dB): ', num2str(snr_calc)]);

figure;
subplot(3,1,1); plot(t, signal_clean, 'b'); title('Toza signal'); grid on;
subplot(3,1,2); plot(t, noise, 'r'); title('Tasodifiy Gauss shovqini'); grid on;
subplot(3,1,3); plot(t, noisy_signal, 'k'); title('Shovqinli signal'); grid on;

figure;
plot(t, signal);
title('Signal');
xlabel('Vaqt (s)');
ylabel('Amplituda');
legend('Asl signal');
grid on;
plot(t, noise);
title('Shovqin');
